#!/bin/bash
# Гейт 1345: ударенная машина трафика (толчок в борт: 10 м/с поперёк и вращение 4 рад/с, встала криво: 4,9 м от оси, курс 46°) — «чпонг» после удара.
# Красный контроль: -DTRF_REJOIN1345_OLD=1. Данные настоящего уровня (level.shr, traffic.shr).
# Зелёное (в кадре): ни одного кадра с переносом > 1 м или разворотом > 0,5 рад; на полосу вернулась своим ходом не раньше 10 и не позже 30 с после удара, встала в 0,5 м от оси.
# Красное (прежнее, в кадре): перенос > 2 м за кадр и разворот > 0,5 рад, возврат через 3 с.
# Вне кадра: перенос не нужен (стоящую вне кадра убирает прежнее правило удаления): ни одного кадра «чпонга» в кадре, машина убрана или вернулась.
cd "$(dirname "$0")/../.."; V=viewer; B=${HOME}/Downloads/shar-psp/build; L=${1:-$B/level.shr}; T=${2:-$B/traffic.shr}; O=${TMPDIR:-/tmp}/trf1345; mkdir -p $O; fail=0
SRC="tests/trf1345/s.c $V/traffic.c $V/homer.c $V/skin.c $V/col.c $V/car.c"
cc -std=c11 -O2 -w -DSKIN_HOST -I $V $SRC -lm -Wl,-undefined,dynamic_lookup -o $O/new || exit 1
cc -std=c11 -O2 -w -DSKIN_HOST -DTRF_REJOIN1345_OLD=1 -I $V $SRC -lm -Wl,-undefined,dynamic_lookup -o $O/old || exit 1
nv=$($O/new $L $T vis 2>&1 | grep "trf1345"); ov=$($O/old $L $T vis 2>&1 | grep "trf1345"); nh=$($O/new $L $T hid 2>&1 | grep -E "trf1345|убрана")
echo "новое, в кадре:  $nv"; echo "прежнее, в кадре: $ov"; echo "новое, вне кадра: $nh" | head -3
g() { echo "$1" | sed -n "s/.*$2 \([-0-9.]*\).*/\1/p" | head -1; }
nj=$(g "$nv" "наибольший перенос за кадр"); nt=$(g "$nv" "разворот за кадр"); nb=$(g "$nv" "вернулась на полосу через"); no=$(g "$nv" "от оси в этот миг")
oj=$(g "$ov" "наибольший перенос за кадр"); ot=$(g "$ov" "разворот за кадр"); ob=$(g "$ov" "вернулась на полосу через")
nc=$(echo "$nv" | sed -n 's/.*в кадре \([0-9]*\), вернулась.*/\1/p')
awk -v j="$nj" -v t="$nt" -v b="$nb" -v o="$no" 'BEGIN { exit !(j <= 1.0 && t <= 0.5 && b >= 10 && b <= 30 && o <= 0.5 && o >= 0) }' || { echo "FAIL новое в кадре: перенос $nj м, разворот $nt, возврат $nb с, от оси $no"; fail=1; }
awk -v j="$oj" -v t="$ot" -v b="$ob" 'BEGIN { exit !(j > 2.0 && t > 0.5 && b > 0 && b < 4) }' || { echo "КРАСНЫЙ НЕ ПОЙМАН: прежнее перенос $oj м, разворот $ot, возврат $ob с"; fail=1; }
echo "$nh" | grep -q "убрана\|вернулась на полосу через [0-9]" || { echo "FAIL вне кадра: ни убрана, ни вернулась"; fail=1; }
[ "${nc:-1}" = 0 ] || { echo "FAIL «чпонгов» в кадре у нового: $nc"; fail=1; }
[ $fail = 0 ] && echo "ГЕЙТ tests/trf1345: PASS" || echo "ГЕЙТ tests/trf1345: FAIL"; exit $fail
